		IRI objectTwo = valueFactory.createIRI("urn:census:fixed-object-two");
		long subjectIdOne = ValueIds.createId(ValueIds.T_URI, 111L);
		long subjectIdTwo = ValueIds.createId(ValueIds.T_URI, 112L);
		long predicateId = ValueIds.createId(ValueIds.T_URI, 211L);
		long objectIdOne = ValueIds.createId(ValueIds.T_URI, 311L);
		long objectIdTwo = ValueIds.createId(ValueIds.T_URI, 312L);

