	@Test
	void distinctSubjectCensusCountsRdfTermsWhenTheSourceHasAliasIds() throws Exception {
		var valueFactory = SimpleValueFactory.getInstance();
		IRI subject = valueFactory.createIRI("urn:census:aliased-subject");
		IRI objectOne = valueFactory.createIRI("urn:census:object-one");
		IRI objectTwo = valueFactory.createIRI("urn:census:object-two");
		long subjectIdOne = ValueIds.createId(ValueIds.T_URI, 101L);
		long subjectIdTwo = ValueIds.createId(ValueIds.T_URI, 102L);
		long predicateId = ValueIds.createId(ValueIds.T_URI, 201L);
		long objectIdOne = ValueIds.createId(ValueIds.T_URI, 301L);
		long objectIdTwo = ValueIds.createId(ValueIds.T_URI, 302L);

		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		when(source.idSpace()).thenReturn(source);
		when(source.hasCanonicalIds()).thenReturn(false);
		when(source.idOf(any(Value.class))).thenAnswer(invocation -> {
			Value value = invocation.getArgument(0);
			if (value.equals(subject)) {
				return subjectIdOne;
			}
			if (value.equals(objectOne)) {
				return objectIdOne;
			}
			if (value.equals(objectTwo)) {
				return objectIdTwo;
			}
			return NativeLmdbQuerySource.UNKNOWN_ID;
		});
		when(source.idOf(any(Value.class), anyInt()))
				.thenAnswer(invocation -> source.idOf(invocation.getArgument(0)));
		Map<Long, Value> termsById = Map.of(subjectIdOne, subject, subjectIdTwo, subject,
				objectIdOne, objectOne, objectIdTwo, objectTwo);
		when(source.lazyValue(anyLong())).thenAnswer(invocation -> term(termsById, invocation.getArgument(0)));
		when(source.lazyValue(anyLong(), anyInt()))
				.thenAnswer(invocation -> term(termsById, invocation.getArgument(0)));

		assertFalse(source.hasCanonicalIds(), "the fixture must not promise a one-ID-per-RDF-term mapping");
		assertNotEquals(subjectIdOne, subjectIdTwo, "the source contains two different IDs for the same RDF term");
		assertEquals(subject, source.lazyValue(subjectIdOne, TripleIndex.SUBJ_IDX));
		assertEquals(subject, source.lazyValue(subjectIdTwo, TripleIndex.SUBJ_IDX));
		assertEquals(subject, source.lazyValue(subjectIdOne));
		assertEquals(subject, source.lazyValue(subjectIdTwo));
		assertNotEquals(objectOne, objectTwo, "the two admitted input occurrences have distinct IRI objects");
		assertEquals(objectOne, source.lazyValue(objectIdOne, TripleIndex.OBJ_IDX));
		assertEquals(objectTwo, source.lazyValue(objectIdTwo, TripleIndex.OBJ_IDX));
		assertEquals(objectOne, source.lazyValue(objectIdOne));
		assertEquals(objectTwo, source.lazyValue(objectIdTwo));
		assertEquals(subjectIdOne, source.idOf(subject, 1 << TripleIndex.SUBJ_IDX),
				"the position-aware lookup must delegate to the same alias-aware source mapping");
		assertEquals(NativeLmdbQuerySource.UNKNOWN_ID,
				source.idOf(valueFactory.createLiteral(BigInteger.ONE), 1 << TripleIndex.OBJ_IDX),
				"an xsd:integer coefficient is not a stored-value ID in this fixture");
		assertEquals(NativeLmdbQuerySource.UNKNOWN_ID,
				source.idOf(valueFactory.createLiteral(1L), 1 << TripleIndex.OBJ_IDX),
				"an xsd:long coefficient is not a stored-value ID in this fixture");
		assertEquals(NativeLmdbQuerySource.UNKNOWN_ID, source.idOf(valueFactory.createLiteral(BigInteger.ONE)),
				"the integer coefficient is not a stored-value ID in this fixture");

		NativeProbe probe = mock(NativeProbe.class);
		WildcardAdjacency wildcard = mock(WildcardAdjacency.class);
		NativeAdjacency adjacency = mock(NativeAdjacency.class);
		NodePredicates subjectProjection = mock(NodePredicates.class);
		when(source.newProbe()).thenReturn(probe);
		when(probe.wildcardAdjacency(true)).thenReturn(wildcard);
		when(wildcard.predicateCount()).thenReturn(1);
		when(wildcard.predicateAt(0)).thenReturn(predicateId);
		when(wildcard.keyCount()).thenReturn(2L);
		when(probe.adjacency(predicateId, true)).thenReturn(adjacency);
		when(probe.nodePredicates(true)).thenReturn(subjectProjection);
		when(subjectProjection.nodeCount()).thenReturn(2L);
		assertEquals(2L, subjectProjection.nodeCount(), "the metadata fixture describes both distinct stored IDs");
		when(adjacency.openPageCursor()).thenAnswer(ignored -> page(subjectIdOne, subjectIdTwo, objectIdOne));
		AdjacencyPageCursor admittedPage = page(subjectIdOne, subjectIdTwo, objectIdOne);
		assertEquals(2, admittedPage.rowCount(), "the actual source page has two accepted root rows");
		assertEquals(2L, admittedPage.quadCount(), "both input occurrences are present before the reduction assertion");
		assertEquals(subjectIdOne, admittedPage.rowAt(0));
		assertEquals(subjectIdTwo, admittedPage.rowAt(1));

		String query = "SELECT (COUNT(DISTINCT ?s) AS ?n) (SUM(IF(isIRI(?o), 1, 0)) AS ?sum) "
				+ "WHERE { ?s ?p ?o }";
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		Group group = group(root);
		LmdbNativeEvaluationStrategy strategy = mock(LmdbNativeEvaluationStrategy.class);
		when(strategy.valuePositionMasks(any(TupleExpr.class))).thenReturn(Map.of());
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);
		QueryEvaluationStep step = LmdbNativeCensusAggregate.tryCreate(group, source, strategy, context, root,
				pattern -> ContextConstraint.UNRESTRICTED);
		assertNotNull(step, "the admitted COUNT(DISTINCT ?s) plus kind SUM uses the existing census path");

		try (CloseableIteration<BindingSet> rows = step.evaluate(EmptyBindingSet.getInstance())) {
			assertTrue(rows.hasNext(), "the two real input occurrences produce one global aggregate row");
			BindingSet result = rows.next();
			assertEquals(valueFactory.createLiteral(BigInteger.ONE), result.getValue("n"),
					"COUNT(DISTINCT ?s) is RDF-term based, even when distinct source IDs alias one term");
			assertEquals(valueFactory.createLiteral(BigInteger.TWO), result.getValue("sum"),
					"the independent kind SUM counts both admitted IRI-object occurrences");
			assertFalse(rows.hasNext());
		}
		verify(adjacency, times(2)).openPageCursor();
	}

	private static Value term(Map<Long, Value> termsById, long id) {
		Value value = termsById.get(id);
		if (value == null) {
			throw new AssertionError("unexpected fixture value ID: " + id);
		}
		return value;
	}

	private static AdjacencyPageCursor page(long subjectOne, long subjectTwo, long object) {
		AdjacencyPageCursor page = mock(AdjacencyPageCursor.class);
		when(page.advance()).thenReturn(true, false);
		when(page.rowCount()).thenReturn(2);
		when(page.quadCount()).thenReturn(2L);
		when(page.rowAt(0)).thenReturn(subjectOne);
		when(page.rowAt(1)).thenReturn(subjectTwo);
		when(page.rowQuadCount(0)).thenReturn(1L);
		when(page.rowQuadCount(1)).thenReturn(1L);
		when(page.firstRow()).thenReturn(subjectOne);
		when(page.firstNeighbor()).thenReturn(object);
		when(page.hasCommonContext()).thenReturn(true);
		when(page.commonContext()).thenReturn(LmdbNativeAggregateCompiler.NULL_CONTEXT_ID);
		when(page.uniformRowTermKind()).thenReturn(true);
		when(page.uniformNeighborTermKind()).thenReturn(true);
		return page;
	}

	private static AdjacencyPageCursor pageWithNeighbors(long subjectOne, long subjectTwo, long objectOne,
			long objectTwo) {
		AdjacencyPageCursor page = mock(AdjacencyPageCursor.class);
		when(page.advance()).thenReturn(true, false);
		when(page.rowCount()).thenReturn(2);
		when(page.fiberCount()).thenReturn(2);
		when(page.quadCount()).thenReturn(2L);
		when(page.firstRow()).thenReturn(subjectOne);
		when(page.firstNeighbor()).thenReturn(objectOne);
		when(page.rowAt(0)).thenReturn(subjectOne);
		when(page.rowAt(1)).thenReturn(subjectTwo);
		when(page.rowQuadCount(0)).thenReturn(1L);
		when(page.rowQuadCount(1)).thenReturn(1L);
		when(page.rowFiberCount(0)).thenReturn(1);
		when(page.rowFiberCount(1)).thenReturn(1);
		when(page.neighborAt(0, 0)).thenReturn(objectOne);
		when(page.neighborAt(1, 0)).thenReturn(objectTwo);
		when(page.copyRowFibers(anyInt(), anyInt(), anyInt(), any(long[].class), anyInt(), any(long[].class),
				anyInt())).thenAnswer(invocation -> {
					int row = invocation.getArgument(0);
					int fromFiber = invocation.getArgument(1);
					int length = invocation.getArgument(2);
					if (fromFiber != 0 || length == 0) {
						return 0;
					}
					long[] neighbors = invocation.getArgument(3);
					int neighborOffset = invocation.getArgument(4);
					long[] multiplicities = invocation.getArgument(5);
					int multiplicityOffset = invocation.getArgument(6);
					neighbors[neighborOffset] = row == 0 ? objectOne : objectTwo;
					multiplicities[multiplicityOffset] = 1L;
					return 1;
				});
		when(page.hasCommonContext()).thenReturn(true);
		when(page.commonContext()).thenReturn(LmdbNativeAggregateCompiler.NULL_CONTEXT_ID);
		when(page.uniformRowTermKind()).thenReturn(true);
		when(page.uniformNeighborTermKind()).thenReturn(true);
		return page;
	}

	private static Group group(TupleExpr root) {
		TupleExpr node = root;
		while (node instanceof UnaryTupleOperator unary && !(node instanceof Group)) {
			node = unary.getArg();
		}
		if (!(node instanceof Group group)) {
			throw new AssertionError("fixture query must have an outer aggregate group");
		}
		return group;
	}
